NUL = 1000

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == NUL:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != NUL]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def hasPathSum(tree, target):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return False
    run = [0] * n
    run[0] = vals[0]
    for k in range(n):
        a, b = left[k], right[k]
        if a == -1 and b == -1:
            if run[k] == target:
                return True
            continue
        if a != -1:
            run[a] = run[k] + vals[a]
        if b != -1:
            run[b] = run[k] + vals[b]
    return False
